var FishingRod = makeKeys()({
  FISHING_ROD: "fishingrod"
});
var fishingRods = registerItems([
  {
    key: FishingRod.FISHING_ROD,
    name: "Basic Fishing Rod",
    description: "A simple rod and reel for catching fish. Ideal for beginners."
  }
]);
function isItemKeyFishingRod(key) {
  return fishingRods.has(key);
}
__name(isItemKeyFishingRod, "isItemKeyFishingRod");
function isItemFishingRod(item) {
  return isItemKeyFishingRod(item.key);
}
__name(isItemFishingRod, "isItemFishingRod");

