// ../source/src/server/prototypes/player/characters/start-game.ts
alt5.Player.prototype.startGame = async function(characterId) {
  const character = await this.loadCharacter(characterId);
  if (!character) {
    return;
  }
  this.setupCharacterStore(character);
  if (isInGame(this)) {
    this.character.inventory.items.filter(({ item }) => !isValidItem(item.key)).forEach(({ slot }) => {
      removeItemFromInventorySlot(this.character.inventory, slot);
    });
  }
  this.updateCharacterAppearance(character.appearance);
  this.spawn(character.lastPosition);
  this.rot = new alt5.Vector3(character.rot);
  this.maxHealth = Math.max(character.health, 2e3);
  this.health = Math.max(character.health, 2e3);
  this.dimension = 0;
  this.emitRaw(ClientEvents.FromServer.START_GAME);
};

