alt24.Player.prototype.equipItem = function(source, equipmentSlot2) {
  const item = findItem(source, this);
  if (!item) {
    alt24.log(`[equipItem] Item not found in source: ${JSON.stringify(source)}`);
    return false;
  }
  const isFromQuickSlot = source.origin === "PlayerEquipment" /* PlayerEquipment */ && [
    "quick1" /* QuickSlot1 */,
    "quick2" /* QuickSlot2 */,
    "quick3" /* QuickSlot3 */,
    "quick4" /* QuickSlot4 */
  ].includes(source.equipmentSlot);
  const isToQuickSlot = [
    "quick1" /* QuickSlot1 */,
    "quick2" /* QuickSlot2 */,
    "quick3" /* QuickSlot3 */,
    "quick4" /* QuickSlot4 */
  ].includes(equipmentSlot2);
  const equipmentSlotOrFishbait = isToQuickSlot ? equipmentSlot2 : isItemFishBait(item) ? "fishbait" : getItemEquipmentSlot(item);
  if (!equipmentSlotOrFishbait) {
    alt24.log(`[equipItem] Item ${item.key} doesn't have equipment slot.`);
    return false;
  }
  const hasInventory = source.origin === "PlayerInventory" /* PlayerInventory */ || source.origin === "Storage" /* Storage */;
  const inventory = hasInventory ? findInventoryByItemSource(source) : null;
  if (hasInventory && !inventory) {
    alt24.log(`[equipItem] Inventory not found for source: ${JSON.stringify(source)}`);
    return false;
  }
  if (equipmentSlotOrFishbait === "fishbait") {
    if (!useFishBaitOnFishingRod(
      {
        equipmentSlot: "tool" /* Tool */,
        origin: "PlayerEquipment" /* PlayerEquipment */,
        originId: this.character.id
      },
      source
    )) {
      return false;
    }
  } else {
    const equipmentSlot3 = equipmentSlotOrFishbait;
    if (isItemKeyClothing(item.key) && // If player gender doesn't match with clothing gender, don't equip
    (this.model === alt24.hash("mp_f_freemode_01") && isMaleClothing(item.key) && !isUnisexClothing(item.key) || this.model === alt24.hash("mp_m_freemode_01") && !isMaleClothing(item.key) && !isUnisexClothing(item.key))) {
      alt24.log(`[equipItem] Player model doesn't match with clothing`);
      return false;
    }
    removeItem(source);
    const unequippedItem = this.character.equipment[equipmentSlot3];
    const isSameAmmo = isItemAmmo(item) && unequippedItem?.key === item.key;
    if (isSameAmmo) {
      this.character.equipment[equipmentSlot3].amount += item.amount;
    } else {
      if (unequippedItem && !isFromQuickSlot) {
        if (inventory) {
          if (!addItemToInventory(inventory, unequippedItem)) {
            alt24.log(`[equipItem] Failed to add unequipped item to inventory`);
            return false;
          }
        } else {
          dropItemOnTheGround(unequippedItem, this.pos);
        }
      }
      this.character.equipment[equipmentSlot3] = item;
      if (isFromQuickSlot) {
        this.character.equipment[source.equipmentSlot] = unequippedItem;
        alt24.log(`[equipItem] Moved item from quick slot to equipment slot`, {
          from: source.equipmentSlot,
          to: equipmentSlot3
        });
      }
    }
  }
  if (!isToQuickSlot) {
    emit(ServerEvents.FromServer.ITEM_EQUIP, this, item);
  }
  return true;
};

