alt39.Events.onWeaponDamage(
  ({ source, target, damage, weaponHash, bodyPart, cancel, setDamageValue }) => {
    if (source.type === alt39.Enums.BaseObjectType.PED && target.type === alt39.Enums.BaseObjectType.PED) {
      alt39.log("ignore friendly fire between enemy peds");
      return cancel();
    }
    if (source.type !== alt39.Enums.BaseObjectType.PLAYER) {
      return;
    }
    if (!isInGame(source)) {
      return cancel();
    }
    const equipedWeapon = source.character.equipment.weapon;
    if (!equipedWeapon) {
      return cancel();
    }
    const weaponInfo = getItemInfoByKey(equipedWeapon.key);
    if (weaponInfo.hash !== weaponHash) {
      return cancel();
    }
    if (!isItemFirearmWeapon(equipedWeapon)) {
      return cancel();
    }
    const ammo2 = isWeaponWithClip(equipedWeapon.key) ? equipedWeapon.clip : source.getEquipedItemInSlot(getWeaponAmmoEquipmentSlot(equipedWeapon.key));
    if (!ammo2) {
      return cancel();
    }
    const weaponDamage = getWeaponDamage(equipedWeapon.key, equipedWeapon.grade);
    const ammoDamage = weaponDamage * getAmmoDamageMultiplier(ammo2.key, ammo2.grade) - weaponDamage;
    const bodyPartDamage = weaponDamage * getBodyPartDamageMultiplier(bodyPart) - weaponDamage;
    const totalDamage = weaponDamage + ammoDamage + bodyPartDamage;
    if (totalDamage > 0) {
      setDamageValue(totalDamage);
      if (target instanceof alt39.Ped) {
        const newHealth = Math.max(
          PED_HEALTH_ZERO,
          Math.min(target.maxHealth, target.health - totalDamage)
        );
        target.health = newHealth;
      }
      if (weaponDamage + bodyPartDamage > 0) {
        source.emit(
          ClientEvents.FromServer.DISPLAY_DAMAGE_HIT,
          target.type,
          target.id,
          weaponDamage + bodyPartDamage,
          "health"
        );
      }
      if (ammoDamage > 0) {
        source.emit(
          ClientEvents.FromServer.DISPLAY_DAMAGE_HIT,
          target.type,
          target.id,
          ammoDamage,
          "armor"
        );
      }
    } else {
      cancel();
    }
  }
);

