      const min = targetPosition - targetSize / 2;
      const max = targetPosition + targetSize / 2;
      const minAdjusted = Math.max(0, min - Math.max(0, max - 1) - errorMargin);
      const maxAdjusted = Math.min(1, max + Math.min(0, 1 + min) + errorMargin);
