// ../source/src/server/modules/skills/fishing/water-zones.ts
water_zones_default.push({
  x: 4840.571,
  y: -5174.425,
  z: 0,
  radius: 3e3
});
var waterZones = water_zones_default.map((zone) => {
  const colshape = alt48.ColShapeCircle.create({
    // @ts-expect-error remove z when api is fixed
    pos: { x: zone.x, y: zone.y, z: 0 },
    radius: zone.radius
  });
  colshape.meta.isWaterZone = true;
  return colshape;
});
alt48.Events.onEntityColShapeEnter(({ colShape, entity }) => {
  if (entity instanceof alt48.Player && isInGame(entity) && colShape.meta.isWaterZone) {
    if (entity.gameState.flags.has("InFishingArea" /* InFishingArea */)) {
      return;
    }
    entity.gameState.flags.add("InFishingArea" /* InFishingArea */);
  }
});
alt48.Events.onEntityColShapeLeave(({ colShape, entity }) => {
  if (entity instanceof alt48.Player && isInGame(entity) && colShape.meta.isWaterZone) {
    if (waterZones.some((zone) => zone.isEntityIn(entity))) {
      return;
    }
    entity.gameState.flags.delete("InFishingArea" /* InFishingArea */);
  }
});

// ../source/src/server/modules/skills/mining/digging-zones.ts
import alt49 from "@altv/server";
var DIGGING_ZONES = [
  { x: 4747.552734375, y: -4489.9365234375, z: 14.253127098083496, radius: 20 },
  { x: 5316.13427734375, y: -5370.37890625, z: 44.7873649597168, radius: 20 },
  { x: 5270.93017578125, y: -5376.875, z: 54.389320373535156, radius: 15 }
];
var diggingZones = DIGGING_ZONES.map((zone) => {
  const colshape = alt49.ColShapeCircle.create({
    pos: { x: zone.x, y: zone.y },
    radius: zone.radius
  });
  colshape.meta.isDiggingZone = true;
  return colshape;
});
alt49.Events.onEntityColShapeEnter(({ colShape, entity }) => {
  if (entity instanceof alt49.Player && isInGame(entity) && colShape.meta.isDiggingZone) {
    if (entity.gameState.flags.has("InDiggingArea" /* InDiggingArea */)) {
      return;
    }
    entity.gameState.flags.add("InDiggingArea" /* InDiggingArea */);
  }
});
alt49.Events.onEntityColShapeLeave(({ colShape, entity }) => {
  if (entity instanceof alt49.Player && isInGame(entity) && colShape.meta.isDiggingZone) {
    if (diggingZones.some((zone) => zone.isEntityIn(entity))) {
      return;
    }
    entity.gameState.flags.delete("InDiggingArea" /* InDiggingArea */);
  }
});

// ../source/src/server/modules/skills/mining/digging.ts
import alt50 from "@altv/server";
rpc.registerClient(ServerCall.FromClient.START_DIGGING, (player) => {
  needsToBeInGame(player);
  player.gameState.flags.add("IsDigging" /* IsDigging */);
  player.playScenario("WORLD_HUMAN_GARDENER_PLANT");
});
function diggingTick(player) {
  if (!isInGame(player)) {
    return;
  }
  if (!player.gameState.flags.has("IsDigging" /* IsDigging */)) {
    return;
  }
  const luckFactor = Math.random() < 0.5 ? 1 : 2;
  player.character.skills.mining += 30 * luckFactor;
  player.addItem(createItem(Sand.GRAVEL, { amount: 1 * luckFactor }));
}
__name(diggingTick, "diggingTick");
function stopDigging(player) {
  needsToBeInGame(player);
  player.gameState.flags.delete("IsDigging" /* IsDigging */);
  player.applyEquipment();
}
__name(stopDigging, "stopDigging");
alt50.Timers.setInterval(() => {
  alt50.Player.all.forEach(diggingTick);
}, 1e3);
rpc.registerClient(ServerCall.FromClient.STOP_DIGGING, stopDigging);

